# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e3a8a" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">KELAM İLMİNİN FELSEFE VE TABİAT BİLİMLERİYLE İLİŞKİSİ</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="26" fill="#2563eb" rx="6"/>\n  <text x="177" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. KELAM VE FELSEFE İLİŞKİSİ</text>\n  <text x="25" y="94" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Ortak Yönleri:</text>\n  <text x="29" y="108" fill="#1e293b" font-size="9">Varlık (ontoloji), bilgi (epistemoloji), değer ve</text>\n  <text x="29" y="121" fill="#1e293b" font-size="9">varlığın başlangıç-sonunu (<tspan font-style="italic">mebde ve meâd</tspan>)</text>\n  <text x="29" y="134" fill="#1e293b" font-size="9">aklî deliller kullanarak incelemeleri.</text>\n  <text x="25" y="152" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Temel Farkları:</text>\n  <text x="29" y="166" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Felsefe:</tspan> Yalnızca insan aklına dayanır; vahyi</text>\n  <text x="29" y="179" fill="#1e293b" font-size="9">  bağlayıcı bir bilgi kaynağı kabul etmez.</text>\n  <text x="29" y="194" fill="#1e293b" font-size="9">• <tspan font-weight="bold" fill="#1d4ed8">Kelam:</tspan> Vahyi (nakli) temel alır; aklı vahyi</text>\n  <text x="29" y="207" fill="#1e293b" font-size="9">  açıklamak ve savunmak için kullanır. Amacı</text>\n  <text x="29" y="220" fill="#1e293b" font-size="9">  dünya ve ahiret mutluluğunu (saadet-i dâreyn)</text>\n  <text x="29" y="233" fill="#1e293b" font-size="9">  sağlamaktır.</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="26" fill="#16a34a" rx="6"/>\n  <text x="522" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. KELAM VE TABİAT BİLİMLERİ İLİŞKİSİ</text>\n  <text x="370" y="94" fill="#14532d" font-size="9.5" font-weight="bold">• Tabiat Bilimleri (Fizik, Kimya, Biyoloji, Astronomi):</text>\n  <text x="374" y="108" fill="#1e293b" font-size="9">Yalnızca duyularla algılanan maddi âlemi</text>\n  <text x="374" y="121" fill="#1e293b" font-size="9">deney ve gözlemle inceler; olayların</text>\n  <text x="374" y="135" fill="#15803d" font-size="9.5" font-weight="bold">"NASIL" gerçekleştiğini açıklar.</text>\n  <text x="370" y="155" fill="#14532d" font-size="9.5" font-weight="bold">• Kelam İlminin Bakış Açısı:</text>\n  <text x="374" y="169" fill="#1e293b" font-size="9">Tabiat bilimleriyle ortaya konan kâinattaki</text>\n  <text x="374" y="182" fill="#1e293b" font-size="9">hassas düzen ve işleyişten hareketle varlığın</text>\n  <text x="374" y="196" fill="#15803d" font-size="9.5" font-weight="bold">"NEDEN ve NİÇİN" yaratıldığını,</text>\n  <text x="374" y="210" fill="#1e293b" font-size="9">ilk sebebi (Yaratıcıyı / Allah\'ı) ve fizik ötesi</text>\n  <text x="374" y="223" fill="#1e293b" font-size="9">(metafizik / ahiret) âlemi temellendirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#4c1d95" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">KELAM İLMİNİN BİLGİ KAYNAKLARI, YÖNTEMİ VE AKIL YÜRÜTME YOLLARI</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#f5f3ff" stroke="#8b5cf6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="26" fill="#6d28d9" rx="6"/>\n  <text x="177" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. KELAMDA ÜÇ BİLGİ KAYNAĞI (ESBÂB-I İLİM)</text>\n  <text x="25" y="96" fill="#4c1d95" font-size="9.5" font-weight="bold">• 1. Doğru Haber (Haber-i Sâdık / Vahiy-Nakil):</text>\n  <text x="29" y="110" fill="#1e293b" font-size="9">Mütevatir haber ve Peygamberlerden gelen</text>\n  <text x="29" y="123" fill="#1e293b" font-size="9">kesin vahiy bilgisi (Kur\'an ve mütevatir sünnet).</text>\n  <text x="25" y="142" fill="#4c1d95" font-size="9.5" font-weight="bold">• 2. Selim Akıl (Akl-ı Selîm):</text>\n  <text x="29" y="156" fill="#1e293b" font-size="9">Ön yargı ve tutkudan arınmış sağlıklı düşünme</text>\n  <text x="29" y="169" fill="#1e293b" font-size="9">yetisi (Mülk, 10: "Kulak verseydik veya</text>\n  <text x="29" y="182" fill="#1e293b" font-size="9">akletseydik..."; Mü\'minûn, 80).</text>\n  <text x="25" y="201" fill="#4c1d95" font-size="9.5" font-weight="bold">• 3. Salim Duyular (Havâss-ı Selîme):</text>\n  <text x="29" y="215" fill="#1e293b" font-size="9">Dış dünyayı gözlemleyen sağlıklı beş duyu</text>\n  <text x="29" y="228" fill="#1e293b" font-size="9">(Şûrâ, 29: Göklerin ve yerin yaratılışı delili).</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="26" fill="#db2777" rx="6"/>\n  <text x="522" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. AKIL YÜRÜTME YÖNTEMLERİ VE DELİLLER</text>\n  <text x="370" y="96" fill="#831843" font-size="9.5" font-weight="bold">• Tümevarım (İstikrâ):</text>\n  <text x="374" y="110" fill="#1e293b" font-size="9">Evrendeki tekil olay ve varlıklardaki düzenden</text>\n  <text x="374" y="123" fill="#1e293b" font-size="9">genel ilkeye (Yaratıcının varlığına) ulaşmak.</text>\n  <text x="370" y="142" fill="#831843" font-size="9.5" font-weight="bold">• Tümdengelim (Ta\'lîl / Kıyas):</text>\n  <text x="374" y="156" fill="#1e293b" font-size="9">Tümel ve genel önermelerden hareketle</text>\n  <text x="374" y="169" fill="#1e293b" font-size="9">özel/tikel sonuçlara ulaşmak.</text>\n  <text x="370" y="188" fill="#831843" font-size="9.5" font-weight="bold">• Analoji (Temsil / Gâibi Şâhide Kıyas):</text>\n  <text x="374" y="202" fill="#1e293b" font-size="9">Bilinen ve görülen âlemden (şâhid) hareketle</text>\n  <text x="374" y="215" fill="#1e293b" font-size="9">benzerlik kurarak görünmeyen âlemi (gâib /</text>\n  <text x="374" y="228" fill="#1e293b" font-size="9">yeniden dirilişi) açıklamak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="32" fill="#78350f" rx="8"/>\n  <text x="350" y="30" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">KELAM TARİHİNİN 5 TEMEL ESERİ VE MÜELLİFLERİ</text>\n\n  <rect x="15" y="50" width="215" height="96" fill="#fffbeb" stroke="#d97706" stroke-width="1.5" rx="8"/>\n  <text x="122" y="68" fill="#92400e" font-size="10" font-weight="bold" text-anchor="middle">1. el-FIKHU\'L-EKBER</text>\n  <text x="122" y="82" fill="#b45309" font-size="9" font-weight="bold" text-anchor="middle">İmam-ı Azam Ebu Hanife (ö. 767)</text>\n  <line x1="25" y1="87" x2="220" y2="87" stroke="#f59e0b" stroke-width="1"/>\n  <text x="23" y="101" fill="#1e293b" font-size="8.5">• İnanç esaslarını "en büyük fıkıh" sayan</text>\n  <text x="23" y="114" fill="#1e293b" font-size="8.5">  ilk dönem kurucu akaid risalesidir.</text>\n  <text x="23" y="127" fill="#1e293b" font-size="8.5">• En meşhur şerhi <tspan font-weight="bold">Aliyyü\'l-Kârî</tspan>\'ye</text>\n  <text x="23" y="139" fill="#1e293b" font-size="8.5">  aittir.</text>\n\n  <rect x="242" y="50" width="215" height="96" fill="#ecfdf5" stroke="#059669" stroke-width="1.5" rx="8"/>\n  <text x="350" y="68" fill="#065f46" font-size="10" font-weight="bold" text-anchor="middle">2. KİTÂBÜ\'T-TEVHÎD</text>\n  <text x="350" y="82" fill="#047857" font-size="9" font-weight="bold" text-anchor="middle">İmam Mâtürîdî (ö. 944)</text>\n  <line x1="252" y1="87" x2="447" y2="87" stroke="#10b981" stroke-width="1"/>\n  <text x="250" y="101" fill="#1e293b" font-size="8.5">• Mâtürîdî kelam ekolünü sistemleştiren,</text>\n  <text x="250" y="114" fill="#1e293b" font-size="8.5">  nakil ve akla dayalı ilk sistematik eser.</text>\n  <text x="250" y="127" fill="#1e293b" font-size="8.5">• Mukaddime + İlahiyat, Nübüvvet, Kader,</text>\n  <text x="250" y="139" fill="#1e293b" font-size="8.5">  Büyük Günah ve Ahiret (5 bölüm).</text>\n\n  <rect x="470" y="50" width="215" height="96" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5" rx="8"/>\n  <text x="577" y="68" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">3. el-İBÂNE AN USÛLİ\'D-DİYÂNE</text>\n  <text x="577" y="82" fill="#1d4ed8" font-size="9" font-weight="bold" text-anchor="middle">Ebu\'l-Hasan el-Eş\'arî (ö. 936)</text>\n  <line x1="480" y1="87" x2="675" y2="87" stroke="#3b82f6" stroke-width="1"/>\n  <text x="478" y="101" fill="#1e293b" font-size="8.5">• Eş\'arî ekolünün kurucu metnidir; 14</text>\n  <text x="478" y="114" fill="#1e293b" font-size="8.5">  bölümden oluşur, Mu\'tezile\'yi eleştirir.</text>\n  <text x="478" y="127" fill="#1e293b" font-size="8.5">• Rü\'yetullah, halku\'l-Kur\'an, haberî</text>\n  <text x="478" y="139" fill="#1e293b" font-size="8.5">  sıfatlar, kader, şefaat ve imameti işler.</text>\n\n  <rect x="15" y="155" width="330" height="92" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5" rx="8"/>\n  <text x="180" y="173" fill="#4c1d95" font-size="10" font-weight="bold" text-anchor="middle">4. MÂTÜRÎDİYYE AKÂİDİ (el-Bidâye fî Usûli\'d-Dîn)</text>\n  <text x="180" y="187" fill="#6d28d9" font-size="9" font-weight="bold" text-anchor="middle">Nûreddin es-Sâbûnî (ö. 1184)</text>\n  <line x1="25" y1="192" x2="335" y2="192" stroke="#8b5cf6" stroke-width="1"/>\n  <text x="25" y="207" fill="#1e293b" font-size="8.8">• Buharalı Mâtürîdî âlimi es-Sâbûnî\'nin daha önce yazdığı</text>\n  <text x="25" y="220" fill="#1e293b" font-size="8.8">  hacimli <tspan font-weight="bold">el-Kifâye</tspan> adlı eserini özetleyerek oluşturduğu</text>\n  <text x="25" y="233" fill="#1e293b" font-size="8.8">  açık ve sistematik klasik kelam el kitabıdır.</text>\n\n  <rect x="355" y="155" width="330" height="92" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5" rx="8"/>\n  <text x="520" y="173" fill="#831843" font-size="10" font-weight="bold" text-anchor="middle">5. KELAM İLMİNE GİRİŞ</text>\n  <text x="520" y="187" fill="#be185d" font-size="9" font-weight="bold" text-anchor="middle">Prof. Dr. Bekir Topaloğlu (1936–2016)</text>\n  <line x1="365" y1="192" x2="675" y2="192" stroke="#ec4899" stroke-width="1"/>\n  <text x="365" y="207" fill="#1e293b" font-size="8.8">• Son dönemde kaleme alınan çağdaş kelam eseridir.</text>\n  <text x="365" y="220" fill="#1e293b" font-size="8.8">• 1. Bölümde kelam tarihi, kaynakları ve metotlarını;</text>\n  <text x="365" y="233" fill="#1e293b" font-size="8.8">  2. Bölümde ise itikadi mezhepleri inceler.</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
